@scope (#chapter-ch6-noisy-capacity){.nm-chapter{--ink:#1a2b4a;--muted:#5b6b7f;--accent:#007acc;--warm:#b74b2b;--line:#d9dde3;--paper:#f7f8fa;color:var(--ink);font-family:Source Serif Pro,Georgia,serif;font-size:16px;line-height:1.6;}
.nm-header{margin-bottom:18px;}
.nm-title{font-size:28px;margin:0 0 6px 0;color:var(--ink);}
.nm-lead{font-size:16px;color:var(--muted);margin:0;}
