.nm-label{display:block;font-size:14px;color:var(--muted);margin:8px 0 4px 0;}
.nm-readout{font-size:13px;color:var(--muted);margin-top:4px;}
.nm-buttons{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px;}
.nm-btn,.nm-src-btn,.nm-con-btn,.nm-ask-btn{font-size:13px;padding:6px 10px;border:1px solid var(--line);background:#fff;color:var(--ink);border-radius:6px;cursor:pointer;}
.nm-btn:hover,.nm-src-btn:hover,.nm-con-btn:hover,.nm-ask-btn:hover{border-color:var(--accent);color:var(--accent);}
.nm-results{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-top:10px;}
.nm-kpi{border:1px solid var(--line);border-radius:8px;padding:10px;background:#fff;}
.nm-kpi-title{font-size:13px;color:var(--muted);}
.nm-kpi-value{font-size:18px;font-weight:600;margin-top:4px;}
.nm-unit{font-size:12px;color:var(--muted);font-weight:400;}
.nm-note{grid-column:1/-1;font-size:13px;color:var(--muted);margin-top:6px;}
.nm-stage canvas{width:100%;height:320px;display:block;border:1px solid var(--line);border-radius:8px;background:#fff;}
.nm-legend{display:flex;gap:12px;margin-top:8px;font-size:13px;color:var(--muted);}
.nm-dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:6px;}
.nm-dot-hxy{background:#c62828;}
.nm-dot-r{background:#1565c0;}
.nm-dot-c{background:#2e7d32;}
.nm-critical{font-size:13px;color:var(--warm);margin-top:8px;}
.nm-footer{margin-top:18px;border-top:1px solid var(--line);padding-top:12px;}
.nm-h3{font-size:18px;margin:0 0 8px 0;}
.nm-list{margin:0 0 10px 18px;padding:0;}
.nm-list li{margin:4px 0;font-size:15px;}
.nm-sources{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px;}
