    // Data Generation
    const maxN = 10;
    const maxStates = Math.pow(2, maxN);
    const maxBits = maxN;

    // Scale factors
    // We need to fit both linear (max 10) and exponential (max 1024) on same chart
    // To make it visible, we might need a log scale for Y or just show the divergence clearly
    // Let's use a linear scale but cap the visual height for states to show it goes 'off chart' or normalize
    // Actually, standard pedagogy shows them diverging. Let's normalize States to fit height, and Bits to fit height.

    const xStep = (width - 2 * padding) / maxN;

    // Draw States Curve (Exponential)
    ctx.beginPath();
    ctx.strokeStyle = '#d9534f'; // Red
    ctx.lineWidth = 2;
    for (let n = 0; n <= maxN; n++) {
      const val = Math.pow(2, n);
      const normalizedVal = val / maxStates; // 0 to 1
      const x = padding + n * xStep;
      const y = height - padding - (normalizedVal * (height - 2 * padding));
      if (n === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // Draw Bits Line (Linear)
    ctx.beginPath();
    ctx.strokeStyle = '#007acc'; // Blue
    ctx.lineWidth = 2;
    for (let n = 0; n <= maxN; n++) {
      const val = n;
      const normalizedVal = val / maxBits; // 0 to 1
      const x = padding + n * xStep;
      const y = height - padding - (normalizedVal * (height - 2 * padding));
      if (n === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

