    const currX = padding + currentN * xStep;
    const currStatesY = height - padding - ((Math.pow(2, currentN) / maxStates) * (height - 2 * padding));
    const currBitsY = height - padding - ((currentN / maxBits) * (height - 2 * padding));

    // Dot for States
    ctx.fillStyle = '#d9534f';
    ctx.beginPath();
    ctx.arc(currX, currStatesY, 4, 0, Math.PI * 2);
    ctx.fill();

    // Dot for Bits
    ctx.fillStyle = '#007acc';
    ctx.beginPath();
    ctx.arc(currX, currBitsY, 4, 0, Math.PI * 2);
    ctx.fill();
  }

  function updateDisplay() {
    const n = parseInt(slider.value, 10);
    const states = Math.pow(2, n);

